import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useStore } from '../../store/useStore';

export default function ExamInterface({ exam, submissionId, onComplete }) {
  var store = useStore();
  var [questions, setQuestions] = useState([]);
  var [answers, setAnswers] = useState({});
  var [currentQ, setCurrentQ] = useState(0);
  var [timeLeft, setTimeLeft] = useState(exam.duration_minutes * 60);
  var [violations, setViolations] = useState(0);
  var [showWarning, setShowWarning] = useState(false);
  var [showConfirm, setShowConfirm] = useState(false);
  var [loading, setLoading] = useState(true);
  var [submitting, setSubmitting] = useState(false);
  var cheatedRef = useRef(false);
  var violationRef = useRef(0);

  useEffect(function() {
    store.loadQuestions(exam.exam_id).then(function(qs) { setQuestions(qs); setLoading(false); });
  }, []); // eslint-disable-line

  // Timer
  useEffect(function() {
    var timer = setInterval(function() {
      setTimeLeft(function(prev) {
        if (prev <= 1) { clearInterval(timer); handleSubmit(false); return 0; }
        return prev - 1;
      });
    }, 1000);
    return function() { clearInterval(timer); };
  }, [questions]); // eslint-disable-line

  // Anti-cheat
  var handleVisibility = useCallback(function() {
    if (document.hidden) {
      violationRef.current++;
      setViolations(violationRef.current);
      if (violationRef.current === 1) { setShowWarning(true); }
      if (violationRef.current >= 2) { cheatedRef.current = true; handleCheatSubmit(); }
    }
  }, []); // eslint-disable-line

  useEffect(function() {
    document.addEventListener('visibilitychange', handleVisibility);
    return function() { document.removeEventListener('visibilitychange', handleVisibility); };
  }, [handleVisibility]);

  async function handleCheatSubmit() {
    setSubmitting(true);
    try {
      await store.submitExam(submissionId, [], exam.exam_id, true);
    } catch (e) {}
    onComplete();
  }

  async function handleSubmit(confirmed) {
    if (!confirmed && !showConfirm) { setShowConfirm(true); return; }
    setSubmitting(true);
    var ansArr = questions.map(function(q) {
      return { question_id: q.question_id, answer_text: answers[q.question_id] || '' };
    });
    try {
      await store.submitExam(submissionId, ansArr, exam.exam_id, cheatedRef.current);
    } catch (e) {}
    onComplete();
  }

  function setAnswer(qid, val) {
    var a = Object.assign({}, answers);
    a[qid] = val;
    setAnswers(a);
  }

  var mins = Math.floor(timeLeft / 60);
  var secs = timeLeft % 60;
  var timeStr = String(mins).padStart(2, '0') + ':' + String(secs).padStart(2, '0');
  var isUrgent = timeLeft < 300;

  if (loading) return <div className="loading-center"><div className="spinner"></div><span>Loading exam...</span></div>;

  var q = questions[currentQ];
  var answeredCount = Object.keys(answers).filter(function(k) { return answers[k]; }).length;

  return (
    <div className="fade-up" style={{ maxWidth: 900, margin: '0 auto' }}>
      {/* Header bar */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20, padding: 16, background: 'var(--surface)', borderRadius: 12, border: '1px solid var(--border)' }}>
        <div><div style={{ fontWeight: 700, fontSize: '1.1rem' }}>{exam.title}</div><div style={{ fontSize: '0.8rem', color: 'var(--text3)' }}>{answeredCount}/{questions.length} answered</div></div>
        <div className={'exam-timer' + (isUrgent ? ' urgent' : '')}>{timeStr}</div>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <span style={{ fontSize: '0.75rem', color: violations > 0 ? 'var(--danger)' : 'var(--text3)' }}>Violations: {violations}/2</span>
          {[0, 1].map(function(i) { return <span key={i} style={{ width: 10, height: 10, borderRadius: '50%', background: i < violations ? 'var(--danger)' : 'var(--border)' }}></span>; })}
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 220px', gap: 20 }}>
        {/* Question area */}
        <div className="card">
          {q && (
            <div>
              <div style={{ display: 'flex', gap: 8, marginBottom: 12 }}>
                <span className="badge badge-primary">Q{currentQ + 1}</span>
                <span className="badge badge-info">{q.marks} marks</span>
                <span className={'badge badge-' + (q.difficulty === 'Easy' ? 'success' : q.difficulty === 'Hard' ? 'danger' : 'warning')}>{q.difficulty}</span>
              </div>
              <div style={{ fontSize: '1.05rem', fontWeight: 500, marginBottom: 20, lineHeight: 1.6 }}>{q.question_text}</div>

              {(q.question_type === 'MCQ' && q.options) && (
                <div>
                  {q.options.map(function(opt, i) {
                    var t = opt.text || opt;
                    var selected = answers[q.question_id] === t;
                    return (
                      <div key={i} onClick={function() { setAnswer(q.question_id, t); }} style={{ padding: '12px 16px', border: '2px solid ' + (selected ? 'var(--accent)' : 'var(--border)'), borderRadius: 10, marginBottom: 10, cursor: 'pointer', background: selected ? 'var(--accent-glow)' : 'var(--surface)', transition: 'var(--transition)', display: 'flex', alignItems: 'center', gap: 12 }}>
                        <span style={{ width: 28, height: 28, borderRadius: '50%', border: '2px solid ' + (selected ? 'var(--accent)' : 'var(--border)'), display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 600, fontSize: '0.8rem', background: selected ? 'var(--accent)' : 'transparent', color: selected ? '#fff' : 'var(--text3)' }}>{String.fromCharCode(65 + i)}</span>
                        <span style={{ fontWeight: selected ? 600 : 400 }}>{t}</span>
                      </div>
                    );
                  })}
                </div>
              )}

              {q.question_type === 'TRUE_FALSE' && (
                <div style={{ display: 'flex', gap: 12 }}>
                  {['True', 'False'].map(function(v) {
                    var selected = answers[q.question_id] === v;
                    return <button key={v} className={'btn ' + (selected ? 'btn-primary' : 'btn-outline')} style={{ flex: 1, justifyContent: 'center' }} onClick={function() { setAnswer(q.question_id, v); }}>{v}</button>;
                  })}
                </div>
              )}

              {(q.question_type === 'SHORT_ANSWER' || q.question_type === 'DESCRIPTIVE') && (
                <textarea className="form-textarea" value={answers[q.question_id] || ''} onChange={function(e) { setAnswer(q.question_id, e.target.value); }} rows={q.question_type === 'DESCRIPTIVE' ? 6 : 3} placeholder="Type your answer..." />
              )}
            </div>
          )}
          <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: 20 }}>
            <button className="btn btn-outline" disabled={currentQ === 0} onClick={function() { setCurrentQ(currentQ - 1); }}>← Previous</button>
            {currentQ < questions.length - 1 ? <button className="btn btn-primary" onClick={function() { setCurrentQ(currentQ + 1); }}>Next →</button> : <button className="btn btn-success" onClick={function() { handleSubmit(false); }}>📤 Submit Exam</button>}
          </div>
        </div>

        {/* Question navigator */}
        <div className="card" style={{ height: 'fit-content' }}>
          <div style={{ fontWeight: 600, marginBottom: 12, fontSize: '0.85rem' }}>Question Navigator</div>
          <div className="question-nav">
            {questions.map(function(q, i) {
              var cls = i === currentQ ? 'current' : answers[q.question_id] ? 'answered' : '';
              return <button key={i} className={cls} onClick={function() { setCurrentQ(i); }}>{i + 1}</button>;
            })}
          </div>
          <button className="btn btn-success btn-sm" style={{ width: '100%', marginTop: 16, justifyContent: 'center' }} onClick={function() { handleSubmit(false); }} disabled={submitting}>📤 Submit</button>
        </div>
      </div>

      {/* Warning modal */}
      {showWarning && (
        <div className="modal-overlay"><div className="modal-content" style={{ textAlign: 'center' }}>
          <div style={{ fontSize: '3rem', marginBottom: 12 }}>⚠️</div>
          <div className="modal-title">Tab Switch Detected!</div>
          <div className="modal-body">You left the exam tab. This is your <strong>first and only warning</strong>. Switching again will <strong>automatically terminate</strong> your exam with a score of 0.</div>
          <button className="btn btn-primary" onClick={function() { setShowWarning(false); }}>I Understand</button>
        </div></div>
      )}

      {/* Submit confirm */}
      {showConfirm && (
        <div className="modal-overlay"><div className="modal-content">
          <div className="modal-title">📤 Submit Exam?</div>
          <div className="modal-body">You have answered {answeredCount} of {questions.length} questions. Are you sure?</div>
          <div className="modal-actions">
            <button className="btn btn-outline" onClick={function() { setShowConfirm(false); }}>Cancel</button>
            <button className="btn btn-success" onClick={function() { handleSubmit(true); }} disabled={submitting}>{submitting ? 'Submitting...' : 'Submit'}</button>
          </div>
        </div></div>
      )}
    </div>
  );
}
